import { addDays, subDays, isWeekend, format, differenceInDays, isBefore, startOfDay } from "date-fns";

/**
 * Parses a "YYYY-MM-DD" date string as local midnight.
 * Using new Date("YYYY-MM-DD") would parse as UTC midnight, which shifts
 * the date back one day in negative-offset (e.g. US) timezones.
 */
export function parseDateStr(dateStr: string): Date {
  const [year, month, day] = dateStr.split("-").map(Number);
  return new Date(year, month - 1, day);
}

export function addBusinessDays(date: Date, amount: number): Date {
  let currentDate = date;
  let addedDays = 0;

  const step = amount > 0 ? 1 : -1;
  const targetDays = Math.abs(amount);

  while (addedDays < targetDays) {
    currentDate = addDays(currentDate, step);
    if (!isWeekend(currentDate)) {
      addedDays++;
    }
  }

  return currentDate;
}

export function subBusinessDays(date: Date, amount: number): Date {
  return addBusinessDays(date, -amount);
}

export function formatDate(dateStr?: string | null): string {
  if (!dateStr) return "-";
  const d = dateStr.includes("T") ? new Date(dateStr) : parseDateStr(dateStr);
  return format(d, "MMM d, yyyy");
}

export function getUrgencyInfo(targetDateStr?: string | null) {
  if (!targetDateStr) return { color: "default", label: "NO DATE", daysRemaining: null, bgClass: "bg-gray-500", textClass: "text-gray-500" };

  const target = startOfDay(targetDateStr.includes("T") ? new Date(targetDateStr) : parseDateStr(targetDateStr));
  const today = startOfDay(new Date());

  const diff = differenceInDays(target, today);

  if (diff < 0)  return { color: "gray",   label: "PAST",        daysRemaining: diff, bgClass: "bg-gray-500",   textClass: "text-gray-500"   };
  if (diff <= 7)  return { color: "red",    label: "URGENT",      daysRemaining: diff, bgClass: "bg-red-500",    textClass: "text-red-500"    };
  if (diff <= 13) return { color: "amber",  label: "CLOSE",       daysRemaining: diff, bgClass: "bg-amber-500",  textClass: "text-amber-500"  };
  if (diff <= 30) return { color: "yellow", label: "SOON",        daysRemaining: diff, bgClass: "bg-yellow-500", textClass: "text-yellow-500" };
  if (diff <= 60) return { color: "green",  label: "IN PROGRESS", daysRemaining: diff, bgClass: "bg-green-500",  textClass: "text-green-500"  };

  return { color: "indigo", label: "PLANNING", daysRemaining: diff, bgClass: "bg-indigo-500", textClass: "text-indigo-500" };
}

export function getCategoryColor(category?: string | null) {
  switch (category) {
    case "Fire Marshal": return "bg-blue-500/10 text-blue-500 hover:bg-blue-500/20";
    case "ID Sign": return "bg-purple-500/10 text-purple-500 hover:bg-purple-500/20";

